// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"nadroparin":{"wirkmechanismus":"Hemmt die Blutgerinnung und verhindert so, dass sich Blutgerinnsel bilden oder vergrössern. Nadroparin ist ein niedermolekulares Heparin, das den körpereigenen Hemmstoff Antithrombin aktiviert; dadurch wird vor allem der Gerinnungsfaktor Xa, in geringerem Mass Thrombin (Faktor IIa), gehemmt. Die Wirkung ist besser vorhersehbar und länger als bei unfraktioniertem Heparin, sodass es ein- bis zweimal täglich unter die Haut gespritzt wird. Die Ausscheidung erfolgt überwiegend über die Nieren.","nebenwirkungen":{"sehrHaeufig":["Blutungen an verschiedenen Stellen (häufiger bei zusätzlichen Risikofaktoren)","Kleiner Bluterguss an der Einstichstelle"],"haeufig":["Reaktionen an der Einstichstelle","Vorübergehender Anstieg der Leberwerte (Transaminasen)"],"selten":["Thrombozytopenie (verminderte Blutplättchen), auch heparininduzierte Thrombozytopenie Typ II mit Thrombosen","Hautausschlag, Nesselsucht, Juckreiz","Kalkablagerungen oder Knötchen an der Einstichstelle"],"sehrSelten":["Überempfindlichkeitsreaktionen bis anaphylaktoide Reaktion, Angioödem","Hyperkaliämie (erhöhtes Kalium)","Hautnekrosen an der Einstichstelle","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)","Priapismus (schmerzhafte Dauererektion)"],"unbekannt":["Spinale oder epidurale Hämatome nach rückenmarksnaher Anästhesie mit möglicher Lähmung"]},"schwangerschaft":"Nur begrenzte Erfahrungen; Anwendung nur nach strenger ärztlicher Abwägung. Für andere niedermolekulare Heparine liegen mehr Daten vor; eine rückenmarksnahe Anästhesie bei der Geburt muss zeitlich abgestimmt werden.","stillzeit":"Nur wenige Daten; eine Aufnahme über den Darm des Säuglings ist unwahrscheinlich. Anwendung nach ärztlicher Abwägung.","hinweise":["Unter die Haut spritzen (Bauch), nie in den Muskel; Einstichstelle wechseln und nicht reiben.","Blutplättchen vor und während der Behandlung kontrollieren lassen (heparininduzierte Thrombozytopenie).","Vor Operationen, Zahnbehandlungen und Spinal- oder Periduralanästhesie die Behandlung angeben.","Bei Blutungszeichen (schwarzer Stuhl, Blut im Urin, ungewöhnliche Blutergüsse) sofort ärztlichen Rat holen."],"darreichung":["Injektionslösung in Fertigspritzen"]},"naftidrofuryl":{"wirkmechanismus":"Verbessert Durchblutung und Stoffwechsel in schlecht durchbluteten Geweben. Naftidrofuryl blockiert Serotonin-5-HT2-Rezeptoren an der Gefässmuskulatur und an den Blutplättchen und wirkt so einer serotoninbedingten Gefässverengung und Plättchenzusammenlagerung entgegen. Zudem verbessert es die Sauerstoff- und Energieverwertung der Zellen.","nebenwirkungen":{"haeufig":["Übelkeit","Bauchschmerzen","Durchfall"],"sehrSelten":["Leberentzündung (Hepatitis) bis Leberversagen","Calciumoxalat-Nierensteine"],"unbekannt":["Hautausschlag und andere allergische Hautreaktionen","Speiseröhrenentzündung (Ösophagitis) bei Einnahme ohne ausreichend Flüssigkeit"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; aus Vorsicht nicht anwenden.","stillzeit":"Nicht bekannt, ob Naftidrofuryl in die Muttermilch übergeht; in der Stillzeit nicht empfohlen.","hinweise":["Tabletten unzerkaut während der Mahlzeiten mit einem grossen Glas Wasser einnehmen und sich danach nicht gleich hinlegen.","Über den Tag ausreichend trinken, um Nierensteinen vorzubeugen.","Gehtraining und Rauchstopp bleiben die wichtigsten Massnahmen bei Schaufensterkrankheit."],"darreichung":["Filmtabletten"]},"naloxegol":{"wirkmechanismus":"Hebt die verstopfende Wirkung von Opioid-Schmerzmitteln im Darm auf, ohne die Schmerzlinderung aufzuheben. Naloxegol ist ein mit Polyethylenglykol verknüpftes (PEGyliertes) Naloxon-Derivat, das die µ-Opioidrezeptoren im Magen-Darm-Trakt blockiert. Da es vom Transporter P-Glykoprotein aus dem Gehirn hinausbefördert wird, gelangt es kaum ins zentrale Nervensystem.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Durchfall"],"haeufig":["Blähungen","Übelkeit","Erbrechen","Kopfschmerzen","Vermehrtes Schwitzen (Hyperhidrose)","Nasen-Rachen-Entzündung"],"gelegentlich":["Opioid-Entzugssyndrom (z. B. Frösteln, Schwitzen, Unruhe, Gähnen)"],"unbekannt":["Überempfindlichkeitsreaktionen","Magen-Darm-Perforation (Durchbruch der Darmwand)"]},"schwangerschaft":"Nicht empfohlen (begrenzte Erfahrungen; beim Ungeborenen sind Entzugssymptome möglich).","stillzeit":"Während der Stillzeit nicht anwenden.","hinweise":["Morgens nüchtern einnehmen, mindestens 30 Minuten vor der ersten Mahlzeit des Tages.","Während der Behandlung keinen Grapefruitsaft trinken.","Bisherige regelmässige Abführmittel werden zu Behandlungsbeginn abgesetzt; bei Bedarf sind Reserve-Abführmittel erlaubt.","Starke, anhaltende oder zunehmende Bauchschmerzen sofort ärztlich melden."],"darreichung":["Filmtabletten"]},"naloxon":{"wirkmechanismus":"Verdrängt Opioide von ihren Bindungsstellen im Gehirn und hebt so ihre Wirkung, vor allem die lebensgefährliche Atemdämpfung, innert Minuten auf. Naloxon ist ein reiner kompetitiver Antagonist an den µ-, κ- und δ-Opioidrezeptoren ohne eigene opioidartige Wirkung. Seine Wirkung hält nur etwa 1–2 Stunden an und ist damit kürzer als die vieler Opioide – die Atemdämpfung kann zurückkehren. Gegen Vergiftungen mit Benzodiazepinen, Alkohol oder anderen Nicht-Opioiden wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Schwindel, Kopfschmerzen","Tachykardie (Herzrasen)","Blutdruckabfall oder -anstieg","Erbrechen","Schmerzen nach Operationen"],"gelegentlich":["Zittern, Schwitzen","Herzrhythmusstörungen, Bradykardie (verlangsamter Puls)","Durchfall, Mundtrockenheit","Hyperventilation (beschleunigte Atmung)","Reizung an der Injektionsstelle"],"selten":["Krampfanfälle"],"sehrSelten":["Allergische Reaktionen bis zum anaphylaktischen Schock","Kammerflimmern, Herzstillstand","Lungenödem (Wasser in der Lunge)","Erythema multiforme (schwere Hautreaktion)"],"unbekannt":["Akutes Opioid-Entzugssyndrom bei Abhängigen (Unruhe, Gänsehaut, Gähnen, Bauchkrämpfe)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden – im Notfall aber ohne Zögern. Bei opioidabhängigen Schwangeren kann auch beim Ungeborenen ein Entzug ausgelöst werden.","stillzeit":"Ob Naloxon in die Muttermilch übergeht, ist nicht bekannt; es wird über den Darm kaum aufgenommen. Gestillte Säuglinge 24 Stunden lang beobachten.","hinweise":["Nach jeder Anwendung sofort den Notruf 144 alarmieren und die Person bis zum Eintreffen des Rettungsdienstes nicht allein lassen – die Wirkung hält kürzer an als die vieler Opioide.","Nasenspray: Person auf den Rücken legen, einen Sprühstoss in ein Nasenloch geben; ohne Besserung nach 2–3 Minuten die zweite Dosis ins andere Nasenloch, danach Seitenlage.","Erneuter Opioidkonsum gegen die Entzugsbeschwerden ist gefährlich: nach dem Abklingen von Naloxon droht erneut eine Überdosis."],"darreichung":["Injektionslösung","Nasenspray (Einzeldosis)"]},"nandrolon":{"wirkmechanismus":"Fördert den Aufbau von Muskel- und Knochengewebe sowie die Blutbildung. Nandrolon ist ein Abkömmling des männlichen Hormons Testosteron (19-Nortestosteron) und bindet an den Androgenrezeptor; im Verhältnis zu Testosteron überwiegt die eiweissaufbauende (anabole) gegenüber der vermännlichenden (androgenen) Wirkung. Es steigert die Bildung von Erythropoetin und regt die Blutbildung im Knochenmark an. Als Decanoat-Ester in Öl wird es nach der Injektion über Wochen langsam freigesetzt.","nebenwirkungen":{"unbekannt":["Vermännlichung bei Frauen: Heiserkeit, tiefere Stimme, Akne, vermehrte Körperbehaarung, Vergrösserung der Klitoris","Zyklusstörungen, Ausbleiben der Regelblutung","Ödeme (Wassereinlagerungen)","Veränderte Blutfette (HDL-Cholesterin sinkt)","Leberfunktionsstörungen; bei hoher Dosierung und Langzeitanwendung Blutzysten in der Leber (Peliosis hepatis) und Lebertumoren","Priapismus (schmerzhafte Dauererektion), Hemmung der Spermienbildung","Hyperkalzämie (erhöhtes Calcium)","Reaktionen an der Injektionsstelle"]},"schwangerschaft":"Kontraindiziert: kann beim weiblichen Kind eine Vermännlichung verursachen.","stillzeit":"Nicht anwenden.","hinweise":["Steht auf der Dopingliste; die Anwendung ist im Wettkampfsport verboten.","Regelmässige Kontrollen von Blutbild, Leberwerten, Blutfetten und bei Männern der Prostata.","Frauen: erste Zeichen einer Vermännlichung (z. B. Heiserkeit) sofort melden, da sie bleibend sein können."],"darreichung":["Ölige Injektionslösung (intramuskulär)"]},"naproxen":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Naproxen hemmt reversibel die Cyclooxygenasen COX-1 und COX-2. Dank der langen Halbwertszeit von 12–17 Stunden genügen meist ein bis zwei Einnahmen pro Tag; die Natrium-Salzform wird schneller aufgenommen und wirkt rascher.","nebenwirkungen":{"haeufig":["Sodbrennen, Dyspepsie (Verdauungsbeschwerden), Übelkeit, Bauchschmerzen","Verstopfung, Durchfall","Kopfschmerzen, Schwindel, Benommenheit","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen)","Ohrensausen (Tinnitus)"],"unbekannt":["Magen-Darm-Geschwüre, -Blutungen und -Durchbrüche","Anaphylaxie (schwere allergische Reaktion) und Asthmaanfälle","Blutbildstörungen bis Agranulozytose (Ausfall der weissen Blutkörperchen)","Hepatitis, Leberschäden","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse); Lichtempfindlichkeit mit Blasenbildung","Nierenschäden bis akutes Nierenversagen","Herzinfarkt, Schlaganfall, Herzinsuffizienz","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach ärztlicher Abwägung, so niedrig dosiert und kurz wie möglich (ab der 20. Woche Risiko für Nierenschäden beim Kind und Fruchtwassermangel). Im letzten Drittel kontraindiziert.","stillzeit":"Geht in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Mit einem Glas Wasser, bei Magenbeschwerden zu einer Mahlzeit einnehmen; Alkohol erhöht das Risiko für Magenblutungen.","So niedrig dosiert und so kurz wie möglich anwenden; rezeptfreie Präparate ohne ärztlichen Rat nur wenige Tage einnehmen.","Kann Schwindel und Benommenheit verursachen – Vorsicht beim Autofahren."],"darreichung":["Tabletten","Filmtabletten"]},"nateglinid":{"wirkmechanismus":"Regt die Bauchspeicheldrüse sehr rasch und nur kurz zur Insulinausschüttung an. Nateglinid, ein Abkömmling der Aminosäure Phenylalanin, schliesst die ATP-abhängigen Kaliumkanäle der Betazellen. Die Insulinfreisetzung beginnt innerhalb von etwa 15 Minuten, ist von der Blutzuckerhöhe abhängig und dauert nur wenige Stunden. Abgebaut wird Nateglinid überwiegend über CYP2C9, zu einem kleineren Teil über CYP3A4.","nebenwirkungen":{"haeufig":["Hypoglykämie (Unterzuckerung)","Bauchschmerzen","Durchfall, Übelkeit, Verdauungsbeschwerden"],"gelegentlich":["Erbrechen"],"selten":["Erhöhte Leberwerte","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Nesselsucht)"]},"schwangerschaft":"Kontraindiziert; ein Diabetes in der Schwangerschaft wird mit Insulin behandelt.","stillzeit":"Kontraindiziert.","hinweise":["Kurz (bis 30 Minuten) vor den Hauptmahlzeiten einnehmen; wird eine Mahlzeit ausgelassen, auch die Tablette auslassen.","Zeichen einer Unterzuckerung kennen und Traubenzucker mitführen; Alkohol erhöht das Risiko.","Unterzuckerungen können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"natriumalginat":{"wirkmechanismus":"Legt sich wie ein schützender Deckel auf den Mageninhalt und hält so Magensäure von der Speiseröhre fern. Im sauren Magen bildet Natriumalginat zusammen mit dem in den Präparaten enthaltenen Hydrogencarbonat (und teils Calcium) ein zähes Gel; das entstehende Kohlendioxid lässt diese Gelschicht («Raft») auf dem Mageninhalt schwimmen. Bei Reflux steigt vor allem das weitgehend säureneutrale Gel in die Speiseröhre auf. Säurebindende Zusätze wie Natrium- oder Kaliumhydrogencarbonat und Calciumcarbonat neutralisieren zusätzlich Magensäure; das Alginat selbst wird nicht ins Blut aufgenommen.","nebenwirkungen":{"sehrSelten":["Anaphylaktische oder anaphylaktoide Reaktionen","Überempfindlichkeitsreaktionen wie Nesselsucht","Atemwegsreaktionen wie Bronchospasmus (Verkrampfung der Atemwege)"],"unbekannt":["Hyperkalzämie, Alkalose oder Milch-Alkali-Syndrom bei hoher, längerer Einnahme calciumhaltiger Präparate","Blähungen und Völlegefühl bei Einnahme grosser Mengen"]},"schwangerschaft":"Kann in der Schwangerschaft angewendet werden; umfangreiche Erfahrungen zeigen keine schädlichen Wirkungen. Natrium- und Calciumgehalt beachten.","stillzeit":"Kann in der Stillzeit angewendet werden.","hinweise":["Nach den Mahlzeiten und vor dem Schlafengehen einnehmen; Suspension vor Gebrauch schütteln, Kautabletten gründlich kauen.","Zu anderen Arzneimitteln etwa 2 Stunden Abstand halten.","Bei kochsalzarmer Diät den Natriumgehalt mit Ärztin, Arzt oder Apotheke besprechen."],"darreichung":["Suspension zum Einnehmen (Flasche oder Beutel)","Kautabletten"]},"natriumchlorid":{"wirkmechanismus":"Ersetzt Wasser und Salz im Raum ausserhalb der Zellen. Natrium und Chlorid sind die wichtigsten Elektrolyte der Körperflüssigkeit ausserhalb der Zellen und bestimmen deren Volumen. Die 0,9 %-Lösung hat etwa die gleiche Teilchenkonzentration wie Blut (isotonisch) und verteilt sich im ganzen Extrazellulärraum, sodass nur etwa ein Viertel in den Blutgefässen bleibt. Weil sie mehr Chlorid enthält als das Blutplasma, kann sie in grossen Mengen eine Übersäuerung (hyperchlorämische Azidose) verursachen. Konzentrierte Lösungen heben den Natriumspiegel gezielt an.","nebenwirkungen":{"unbekannt":["Hypernatriämie (zu hohes Natrium) mit Durst, Unruhe, Verwirrtheit","Hyperchlorämische metabolische Azidose (Übersäuerung) bei grossen Mengen","Überwässerung, Ödeme, Lungenödem, Blutdruckanstieg","Osmotisches Demyelinisierungssyndrom bei zu raschem Ausgleich eines Natriummangels","Reaktionen an der Infusionsstelle (Venenreizung, Venenentzündung, Paravasat)","Fieber, Infektion an der Einstichstelle"]},"schwangerschaft":"Kann angewendet werden; Vorsicht bei Präeklampsie.","stillzeit":"Kann angewendet werden.","hinweise":["Konzentrate (z. B. 11,7 %) nie unverdünnt infundieren – nur als Zusatz zu Infusionslösungen.","Bei Infusionen Elektrolyte, Säure-Basen-Haushalt und Flüssigkeitsbilanz kontrollieren lassen.","Einen chronischen Natriummangel nur langsam ausgleichen (Anstieg des Natriums höchstens etwa 8–10 mmol/l in 24 Stunden)."],"darreichung":["Infusionslösung 0,9 % (isotonisch)","Konzentrat zur Herstellung einer Infusionslösung (z. B. 11,7 %)","Lösung zum Spülen und Verdünnen"]},"natriumcitrat-natriumlaurylsulfoacetat-sorbitol":{"wirkmechanismus":"Weicht den Stuhl im Enddarm auf und erleichtert so eine rasche Entleerung. Die fixe Kombination wirkt rein örtlich: Natriumcitrat verdrängt gebundenes Wasser aus dem Stuhl (peptisierende Wirkung), das Netzmittel Natriumlaurylsulfoacetat lässt Wasser in den harten Stuhl eindringen, und Sorbitol zieht osmotisch Wasser in den Enddarm. Der aufgeweichte Stuhl löst den Entleerungsreflex aus, meist innerhalb von 5 bis 20 Minuten. Die Bestandteile werden kaum in den Körper aufgenommen.","nebenwirkungen":{"unbekannt":["Brennen oder Missempfindungen am After","Bauchschmerzen, Bauchkrämpfe","Weicher Stuhl, Durchfall","Überempfindlichkeitsreaktionen (z. B. Nesselsucht)"]},"schwangerschaft":"Die Bestandteile werden kaum aufgenommen; die Anwendung in der Schwangerschaft ist möglich.","stillzeit":"Anwendung in der Stillzeit möglich.","hinweise":["Kanüle vollständig einführen (bei Kindern unter 3 Jahren nur zur Hälfte), Tube ganz ausdrücken und erst nach dem Herausziehen loslassen.","Abführmittel nur kurzfristig verwenden; bei anhaltender Verstopfung ärztlich abklären lassen."],"darreichung":["Rektallösung (Mikroklistier)"]},"natriumfluorid":{"wirkmechanismus":"Härtet den Zahnschmelz und macht ihn widerstandsfähiger gegen die Säuren, die Kariesbakterien bilden. Fluorid lagert sich an der Zahnoberfläche als calciumfluoridartige Schicht ab, aus der bei einem Säureangriff Fluorid frei wird; dies bremst die Entkalkung (Demineralisation) und fördert die Wiedereinlagerung von Mineralien (Remineralisation) unter Bildung von säurefesterem Fluorapatit. Zusätzlich hemmt Fluorid den Zuckerstoffwechsel der Plaquebakterien. Die Schutzwirkung beruht vor allem auf dem direkten Kontakt mit den Zähnen.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen mit Schwellungen im Mund (Fluoridlack, Kolophonium)","Asthmaanfälle bei Menschen mit Asthma (Fluoridlack)"],"unbekannt":["Zahnfluorose (weissliche bis bräunliche Flecken im Zahnschmelz) bei zu hoher Fluoridzufuhr während der Zahnentwicklung","Übelkeit, Erbrechen und Magenbeschwerden nach Verschlucken grösserer Mengen","Reizung oder Abschuppung der Mundschleimhaut (Zahngel)","Skelettfluorose (Knochenveränderungen) bei langdauernder Überdosierung"]},"schwangerschaft":"Die lokale Anwendung (Zahngel, Fluoridlack) in üblicher Menge ist vertretbar. Fluoridtabletten nur auf ärztlichen oder zahnärztlichen Rat; ein Nutzen für die Zähne des Kindes ist nicht belegt.","stillzeit":"Fluorid geht nur in sehr geringen Mengen in die Muttermilch über; die Anwendung in der Stillzeit ist möglich.","hinweise":["In der Schweiz ist fluoridiertes Speisesalz verbreitet: Fluoridtabletten nur nach Rücksprache mit Zahnärztin, Arzt oder Apotheke geben.","Fluoridtabletten langsam im Mund zergehen lassen, damit das Fluorid direkt auf die Zähne wirkt.","Zahngel nur einmal pro Woche verwenden, nach dem Einbürsten ausspucken und nicht schlucken.","Nach dem Auftragen von Fluoridlack einige Stunden nichts Hartes essen und die Zähne erst am nächsten Tag putzen."],"darreichung":["Tabletten (zum Lutschen)","Zahngel","Fluoridlack (Anwendung in der Zahnarztpraxis)"]},"natriumhydrogencarbonat":{"wirkmechanismus":"Neutralisiert überschüssige Säure im Blut. Bicarbonat ist der wichtigste Puffer des Körpers: Es bindet Wasserstoff-Ionen, wobei Wasser und Kohlendioxid entstehen, das über die Lunge abgeatmet wird. Dadurch steigen pH-Wert und Bicarbonatspiegel im Blut; eine ausreichende Atmung ist Voraussetzung. Über die Niere ausgeschiedenes Bicarbonat macht den Urin basisch, wodurch schwache Säuren wie Salicylate oder Barbiturate besser ausgeschieden werden. Die magensaftresistenten Kapseln geben den Wirkstoff erst im Dünndarm frei, damit im Magen kein Gas entsteht.","nebenwirkungen":{"unbekannt":["Blähungen, Aufstossen, Bauchschmerzen (Kapseln)","Metabolische Alkalose (zu basisches Blut) bei Überdosierung","Hypernatriämie, Überwässerung und Ödeme","Hypokaliämie (Kaliummangel)","Muskelkrämpfe und Tetanie durch Abfall des freien Calciums","Infusion: Venenreizung, Gewebeschäden bei Paravasat"]},"schwangerschaft":"Bei klarer Indikation anwendbar; wegen der Natriumbelastung Vorsicht bei Ödemen und Präeklampsie.","stillzeit":"Kann angewendet werden.","hinweise":["Kapseln unzerkaut mit Flüssigkeit schlucken, nicht öffnen.","Natriumgehalt bei natriumarmer Diät, Herzschwäche oder Bluthochdruck beachten.","Säure-Basen-Haushalt (Blutgasanalyse) und Elektrolyte regelmässig kontrollieren lassen.","Konzentrierte Infusionslösung (8,4 %) möglichst über eine grosse oder zentrale Vene geben."],"darreichung":["Magensaftresistente Weichkapseln","Infusionslösung (z. B. 4,2 % und 8,4 %)"]},"natriumphenylbutyrat":{"wirkmechanismus":"Eröffnet dem Körper einen Ersatzweg, um überschüssigen Stickstoff loszuwerden, wenn der Harnstoffzyklus nicht funktioniert. Natriumphenylbutyrat ist eine Vorstufe (Prodrug) und wird rasch zu Phenylacetat umgewandelt. Phenylacetat verbindet sich mit der stickstoffreichen Aminosäure Glutamin zu Phenylacetylglutamin, das über die Niere ausgeschieden wird. Pro Molekül werden so zwei Stickstoffatome entfernt – wie beim Harnstoff –, was Ammoniak- und Glutaminspiegel im Blut senkt.","nebenwirkungen":{"sehrHaeufig":["Ausbleiben oder Unregelmässigkeit der Monatsblutung (Amenorrhö)"],"haeufig":["Appetitminderung","Geschmacksstörung, unangenehmer Körpergeruch","Bauchschmerzen, Übelkeit, Erbrechen, Verstopfung","Kopfschmerzen, Synkope (Ohnmacht)","Depression, Reizbarkeit","Blutbildveränderungen (Anämie, Mangel an Blutplättchen oder weissen Blutkörperchen)","Störungen des Säure-Basen- und Elektrolythaushalts (z. B. metabolische Azidose, Hypokaliämie), renale tubuläre Azidose","Ödeme (Wassereinlagerungen), Hautausschlag"],"gelegentlich":["Aplastische Anämie (Versagen der Blutbildung)","Blutergüsse (Ekchymosen)","Herzrhythmusstörungen","Gastritis, Magengeschwür, Rektalblutung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Haarausfall"]},"schwangerschaft":"Kontraindiziert (im Tierversuch Schädigung des sich entwickelnden Gehirns). Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Auf die Mahlzeiten des Tages verteilt einnehmen; das Granulat kann mit fester Nahrung oder mit Flüssigkeit gemischt werden.","Eiweissarme Diät und allfällige Ergänzungen (z. B. Aminosäuren) nach Anweisung des Stoffwechselzentrums weiterführen.","Regelmässige Kontrollen von Ammoniak, Aminosäuren, Elektrolyten (v. a. Kalium) und Blutbild."],"darreichung":["Tabletten","Granulat"]},"natriumphosphat":{"wirkmechanismus":"Löst rasch den Stuhlgang aus, indem die Lösung Wasser in den Enddarm zieht. Die stark konzentrierte (hypertone) Phosphatlösung bindet osmotisch Wasser im Rektum und Sigmoid, weicht den Stuhl auf und dehnt die Darmwand; der Dehnungsreiz löst den Entleerungsreflex meist innerhalb von 2 bis 15 Minuten aus. Ein kleiner Teil des Natriums und Phosphats wird über die Darmschleimhaut aufgenommen – bei längerem Verbleiben im Darm, eingeschränkter Nierenfunktion oder bei Kleinkindern kann dies zu gefährlichen Elektrolytstörungen führen.","nebenwirkungen":{"sehrSelten":["Hyperphosphatämie (zu viel Phosphat), Hypokalzämie (Calciummangel), Hypernatriämie, Hypokaliämie","Dehydratation (Austrocknung) und metabolische Azidose (Übersäuerung)","Überempfindlichkeitsreaktionen"],"unbekannt":["Brennen, Reizung oder Schmerzen am After","Bauchkrämpfe, Blähbauch, Übelkeit","Verletzung der Enddarmschleimhaut bei unsachgemässem Einführen","Krampfanfälle oder Herzrhythmusstörungen bei schweren Elektrolytstörungen (z. B. nach Überdosierung oder wenn das Klistier nicht ausgeschieden wird)"]},"schwangerschaft":"Kurzfristige Anwendung nach Rücksprache möglich; wird auch zur Darmentleerung vor der Geburt eingesetzt.","stillzeit":"Natrium und Phosphat können in die Muttermilch übergehen; nur nach Rücksprache anwenden – vorsichtshalber kann die Milch während 24 Stunden abgepumpt und verworfen werden.","hinweise":["Nicht mehr als ein Klistier innerhalb von 24 Stunden und nicht über längere Zeit anwenden.","Erfolgt nach dem Einlauf innert etwa 15 Minuten keine Entleerung, ärztlichen Rat einholen (Gefahr von Elektrolytstörungen).","Liegend auf der linken Seite mit angezogenen Knien vorsichtig einführen; vor und nach der Anwendung genügend trinken."],"darreichung":["Rektallösung (Klistier, Einlauf)"]},"natriumpicosulfat":{"wirkmechanismus":"Regt den Dickdarm an und sorgt für weicheren Stuhl. Natriumpicosulfat ist eine Vorstufe (Prodrug), die unverändert in den Dickdarm gelangt und dort von Darmbakterien zum wirksamen BHPM (Bis-(p-hydroxyphenyl)-pyridyl-2-methan, wie bei Bisacodyl) gespalten wird. Dieses verstärkt die Peristaltik und fördert die Ansammlung von Wasser und Salzen im Darm; die Wirkung tritt nach 6–12 Stunden ein. In der Kombination zur Darmreinigung bildet sich zusätzlich Magnesiumcitrat, das als osmotisches Abführmittel Wasser in den Darm zieht.","nebenwirkungen":{"haeufig":["Durchfall"],"gelegentlich":["Bauchbeschwerden, Bauchschmerzen, Bauchkrämpfe","Übelkeit, Erbrechen","Schwindel"],"unbekannt":["Überempfindlichkeitsreaktionen mit Hautausschlag, Juckreiz oder Angioödem","Kurze Ohnmacht (Synkope)","Darmreinigung: Kopfschmerzen, Schmerzen im Analbereich","Darmreinigung: Natriummangel (Hyponatriämie), Kaliummangel, Magnesiumüberschuss, sehr selten mit Krampfanfällen"]},"schwangerschaft":"Es sind keine schädlichen Wirkungen bekannt; dennoch nur nach ärztlicher Rücksprache anwenden, wenn Ernährungsmassnahmen nicht ausreichen.","stillzeit":"Der Wirkstoff geht nicht nennenswert in die Muttermilch über; Anwendung in der Stillzeit möglich.","hinweise":["Abends einnehmen, die Wirkung tritt am nächsten Morgen ein (nach 6–12 Stunden).","Abführmittel nur kurzzeitig anwenden; bei anhaltender Verstopfung ärztlich abklären lassen.","Bei der Darmreinigung genau nach Anleitung reichlich klare Flüssigkeit trinken, um Austrocknung und Salzverlust zu vermeiden."],"darreichung":["Tropfen","Tabletten","Pulver zur Herstellung einer Lösung (Kombination)"]},"nebivolol":{"wirkmechanismus":"Senkt Puls und Blutdruck, indem es die Wirkung der Stresshormone am Herzen abschwächt und zusätzlich die Blutgefässe weitet. Nebivolol blockiert hoch selektiv und kompetitiv die Beta-1-Adrenozeptoren des Herzens und senkt so Herzfrequenz und Kontraktionskraft. Zusätzlich fördert es die Freisetzung von Stickstoffmonoxid (NO) aus der Gefässinnenwand, was die Gefässe erweitert und den peripheren Widerstand senkt. Nebivolol wird über CYP2D6 abgebaut; bei langsamen Metabolisierern sind die Spiegel höher, die Wirkung ist aber vergleichbar.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel (bei Herzschwäche sehr häufig)","Kribbeln (Parästhesien)","Müdigkeit","Atemnot (Dyspnoe)","Verstopfung, Übelkeit, Durchfall","Ödeme (Wassereinlagerungen)"],"gelegentlich":["Bradykardie (langsamer Puls; bei Herzschwäche sehr häufig)","Verschlechterung einer Herzschwäche, verlangsamte AV-Überleitung bzw. AV-Block","Hypotonie (tiefer Blutdruck)","Bronchospasmus (Verkrampfung der Atemwege)","Albträume, Depression","Sehstörungen","Verstärkte Schaufensterkrankheit (Claudicatio intermittens)","Juckreiz, Hautausschlag, Erektionsstörungen, Verdauungsbeschwerden, Blähungen, Erbrechen"],"sehrSelten":["Synkope (Ohnmacht)","Verschlechterung einer Psoriasis"],"unbekannt":["Angioödem (Schwellung von Gesicht, Lippen, Zunge)","Überempfindlichkeitsreaktionen, Nesselsucht"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung: Betablocker können die Durchblutung der Plazenta vermindern und das Wachstum des Kindes hemmen. Neugeborene in den ersten Lebenstagen auf langsamen Puls und Unterzuckerung überwachen.","stillzeit":"Nicht empfohlen; ob Nebivolol in die Muttermilch übergeht, ist beim Menschen nicht bekannt (im Tierversuch ja).","hinweise":["Nicht abrupt absetzen – Gefahr von Blutdruckanstieg, Herzrasen und Angina-pectoris-Anfällen; ein Absetzen erfolgt schrittweise nach ärztlicher Anweisung.","Zu Beginn können Schwindel und Müdigkeit auftreten; Vorsicht beim Autofahren.","Täglich etwa zur gleichen Zeit einnehmen, unabhängig von den Mahlzeiten.","Vor Operationen und Narkosen die Einnahme angeben."],"darreichung":["Tabletten"]},"nemolizumab":{"wirkmechanismus":"Unterbricht das Juckreiz-Signal und dämpft die Entzündung der Haut. Nemolizumab ist ein humanisierter Antikörper, der an den Interleukin-31-Rezeptor A (IL-31RA) bindet und so die Wirkung von IL-31 blockiert. IL-31 reizt Nervenfasern der Haut und löst Juckreiz aus; zudem fördert es Entzündung und Störungen der Hautbarriere. Der Juckreiz lässt häufig schon in den ersten Behandlungswochen nach.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Ekzem bzw. Aufflammen der Neurodermitis"],"unbekannt":["Überempfindlichkeitsreaktionen (z. B. Nesselsucht, Gesichtsschwellung)","Reaktionen an der Injektionsstelle"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Nemolizumab in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Im Kühlschrank lagern und vor der Zubereitung auf Raumtemperatur kommen lassen; die Anleitung des Fertigpens genau befolgen.","Bei Atemnot, Schwellung von Gesicht oder Lippen nach der Injektion sofort ärztliche Hilfe holen.","Bei Neurodermitis werden in der Regel begleitend Kortison- oder Calcineurinhemmer-Cremes verwendet."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung (Fertigpen)"]},"nifedipin":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Gefässmuskulatur entspannt und die Arterien weitet. Nifedipin blockiert L-Typ-Calciumkanäle in der glatten Muskulatur der peripheren Arterien und der Herzkranzgefässe; der Gefässwiderstand sinkt, die Herzkranzgefässe werden erweitert und Gefässkrämpfe verhindert. Die Retardtablette gibt den Wirkstoff über 24 Stunden gleichmässig frei und mildert so die bei rasch freigesetztem Nifedipin typische reflektorische Pulsbeschleunigung. Nifedipin wird in Darm und Leber über CYP3A4 abgebaut.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Ödeme (Wassereinlagerungen, vor allem an den Beinen)","Flush (Gesichtsrötung mit Wärmegefühl)","Verstopfung","Unwohlsein"],"gelegentlich":["Herzklopfen, beschleunigter Puls","Hypotonie (tiefer Blutdruck), Synkope (Ohnmacht)","Schwindel, Benommenheit, Migräne, Zittern, Schlafstörungen, Angstreaktionen","Übelkeit, Bauchschmerzen, Verdauungsstörungen, Blähungen, Mundtrockenheit","Allergische Reaktionen, allergisches Ödem bzw. Angioödem","Erhöhte Leberwerte","Muskelkrämpfe, Gelenkschwellung","Vermehrtes Wasserlassen, Erektionsstörungen, Sehstörungen, Nasenbluten"],"selten":["Juckreiz, Nesselsucht, Hautausschlag","Kribbeln oder Missempfindungen (Parästhesien)","Zahnfleischwucherung (Gingivahyperplasie)"],"unbekannt":["Agranulozytose, Leukopenie (Mangel an weissen Blutkörperchen)","Anaphylaxie (schwere allergische Reaktion)","Brustschmerzen (Angina pectoris)","Darmverschluss, Bezoar (Tablettenklumpen im Verdauungstrakt), Schluckbeschwerden, Erbrechen","Gelbsucht (Ikterus)","Toxische epidermale Nekrolyse, Lichtempfindlichkeit","Hyperglykämie (erhöhter Blutzucker)","Atemnot, Lungenödem"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung; im Tierversuch fruchtschädigend. Zusammen mit Magnesiumsulfat i. v. droht ein übermässiger Blutdruckabfall.","stillzeit":"Nifedipin geht in die Muttermilch über; während der Behandlung wird vom Stillen abgeraten.","hinweise":["Retardtablette unzerkaut mit Flüssigkeit schlucken, nicht teilen; die leere Tablettenhülle kann im Stuhl sichtbar sein – das ist normal.","Grapefruit und Grapefruitsaft meiden.","Bei neuen oder stärkeren Brustschmerzen nach Behandlungsbeginn sofort ärztlich melden.","Zu Beginn sind Schwindel und Kopfschmerzen möglich; Vorsicht beim Autofahren, besonders zusammen mit Alkohol."],"darreichung":["Retardtabletten (Tabletten mit verzögerter Wirkstofffreisetzung)"]},"nikotin":{"wirkmechanismus":"Ersetzt beim Rauchstopp einen Teil des Nikotins aus dem Tabak und lindert so Entzugssymptome und Rauchverlangen – ohne Teer, Kohlenmonoxid und die übrigen Schadstoffe des Rauchs. Nikotin ist ein Agonist an nikotinischen Acetylcholinrezeptoren im Gehirn, im vegetativen Nervensystem und an der Muskulatur; im Belohnungssystem setzt es Dopamin frei. Aus Pflaster, Kaugummi, Lutschtablette oder Spray wird es langsamer und in tieferer Konzentration aufgenommen als beim Rauchen, was das Abhängigkeitspotenzial senkt.","nebenwirkungen":{"sehrHaeufig":["Hautreizung an der Pflasterstelle (Rötung, Juckreiz)","Kopfschmerzen","Übelkeit","Schluckauf, Reizung von Mund und Rachen (Kaugummi, Lutschtablette, Spray, Inhalator)"],"haeufig":["Schwindel","Geschmacksstörungen, Kribbeln im Mund","Erbrechen, Durchfall, Bauchschmerzen, Blähungen, Dyspepsie (Verdauungsbeschwerden)","Mundtrockenheit, vermehrter Speichelfluss, Entzündung der Mundschleimhaut","Schlafstörungen und lebhafte Träume (Pflaster)","Husten","Müdigkeit","Überempfindlichkeitsreaktionen"],"gelegentlich":["Herzklopfen, Herzrasen","Hautrötung (Flush), Bluthochdruck","Bronchospasmus (Verkrampfung der Atemwege), Atemnot","Nesselsucht, Hautausschlag, vermehrtes Schwitzen","Kieferschmerzen, Muskelschmerzen","Schwäche, Brustbeschwerden"],"selten":["Vorhofflimmern"],"unbekannt":["Anaphylaxie, Angioödem","Krampfanfälle","Verschwommenes Sehen"]},"schwangerschaft":"Ein Rauchstopp ohne Medikamente ist anzustreben. Gelingt das nicht, ist eine Nikotinersatztherapie nach ärztlicher Rücksprache besser als Weiterrauchen; Kaugummi, Lutschtablette oder Spray sind dem Pflaster vorzuziehen.","stillzeit":"Nikotin geht in die Muttermilch über; nur nach ärztlicher Rücksprache und kurz wirksame Formen möglichst unmittelbar nach dem Stillen anwenden.","hinweise":["Kaugummi langsam kauen und zwischendurch in der Backe «parken»; 15 Minuten vor und während der Anwendung keine sauren Getränke wie Kaffee oder Fruchtsaft (vermindern die Aufnahme).","Für Kinder unzugänglich aufbewahren und gebrauchte Pflaster zusammengefaltet entsorgen – schon kleine Mengen können für Kinder lebensgefährlich sein.","Pflaster täglich an einer anderen Hautstelle aufkleben; bei Schlafstörungen das Pflaster vor dem Schlafengehen entfernen.","Nach dem Rauchstopp können die Spiegel bestimmter Medikamente (z. B. Clozapin, Theophyllin) steigen – Ärztin oder Arzt informieren."],"darreichung":["Transdermale Pflaster","Kaugummis","Lutschtabletten","Sublingualtabletten","Mundspray","Inhalator"]},"nintedanib":{"wirkmechanismus":"Bremst die Vernarbung (Fibrosierung) des Lungengewebes. Nintedanib hemmt mehrere Rezeptor-Tyrosinkinasen – die Rezeptoren für die Wachstumsfaktoren PDGF, FGF und VEGF – sowie Kinasen der Src-Familie. Dadurch werden Vermehrung, Wanderung und Umwandlung von Fibroblasten zu Myofibroblasten gehemmt, die bei Lungenfibrosen übermässig Bindegewebe bilden. Die Hemmung des VEGF-Signalwegs erklärt Nebenwirkungen wie Blutungen und Blutdruckanstieg.","nebenwirkungen":{"sehrHaeufig":["Durchfall","Übelkeit","Bauchschmerzen","Erhöhte Leberwerte"],"haeufig":["Erbrechen","Appetitlosigkeit, Gewichtsverlust","Blutungen (z. B. Nasenbluten)","Bluthochdruck"],"gelegentlich":["Herzinfarkt","Pankreatitis (Bauchspeicheldrüsenentzündung)","Kolitis (Dickdarmentzündung)","Thrombozytopenie (Mangel an Blutplättchen)","Arzneimittelbedingter Leberschaden, erhöhtes Bilirubin","Hautausschlag, Juckreiz, Haarausfall","Proteinurie (Eiweiss im Urin)"],"unbekannt":["Aneurysmen und Arteriendissektionen (Gefässaussackungen und -einrisse)","Magen-Darm-Perforation (Darmdurchbruch)","Nierenversagen"]},"schwangerschaft":"Kontraindiziert (im Tierversuch fruchtschädigend). Frauen im gebärfähigen Alter brauchen vor Beginn einen Schwangerschaftstest und müssen während sowie mindestens 3 Monate nach der Behandlung hochwirksam verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden mit einer Mahlzeit unzerkaut mit Wasser schlucken; Kapseln nicht öffnen.","Bei Durchfall früh reichlich trinken und ein Mittel gegen Durchfall (z. B. Loperamid) nach ärztlicher Anweisung einnehmen.","Die Leberwerte werden in den ersten 3 Monaten monatlich, danach regelmässig kontrolliert.","Wegen möglichem Durchfall oder Erbrechen bei hormonaler Verhütung zusätzlich ein Kondom verwenden."],"darreichung":["Weichkapseln"]},"nirmatrelvir-ritonavir":{"wirkmechanismus":"Hemmt die Vermehrung des Coronavirus SARS-CoV-2. Nirmatrelvir blockiert die Hauptprotease des Virus (Mpro, 3CL-Protease), die die viralen Polyproteine in funktionsfähige Einzelproteine zerschneidet; ohne diesen Schritt kann sich das Virus nicht vermehren. Ritonavir wirkt nicht gegen SARS-CoV-2, hemmt aber stark das Abbauenzym CYP3A4 und erhöht so die Nirmatrelvir-Spiegel. Diese CYP3A-Hemmung ist die Ursache der vielen Wechselwirkungen und hält nach Behandlungsende noch einige Tage an.","nebenwirkungen":{"haeufig":["Geschmacksstörung (Dysgeusie)","Durchfall","Kopfschmerzen","Übelkeit, Erbrechen"],"gelegentlich":["Bauchschmerzen","Bluthochdruck","Muskelschmerzen","Hautausschlag, Juckreiz","Überempfindlichkeitsreaktionen"],"selten":["Anaphylaxie (schwere allergische Reaktion)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Unwohlsein"]},"schwangerschaft":"Nicht empfohlen, ausser der klinische Zustand erfordert die Behandlung. Frauen im gebärfähigen Alter sollen während der Behandlung wirksam verhüten (hormonale Verhütung ist abgeschwächt).","stillzeit":"Während der Behandlung und bis 48 Stunden nach der letzten Dosis nicht stillen.","hinweise":["Vor Beginn alle Medikamente, auch pflanzliche und rezeptfreie, mit Ärztin, Arzt oder Apotheke prüfen – viele Dauermedikamente müssen pausiert oder angepasst werden.","So früh wie möglich, spätestens 5 Tage nach Symptombeginn beginnen; 5 Tage lang zweimal täglich alle Tabletten einer Dosis zusammen einnehmen, mit oder ohne Essen, ganz schlucken.","Die Hemmung des Abbauenzyms hält nach der letzten Dosis noch 2–3 Tage an – pausierte Medikamente erst nach ärztlicher Anweisung wieder beginnen."],"darreichung":["Filmtabletten (Kombipackung)"]},"nirsevimab":{"wirkmechanismus":"Gibt dem Säugling sofort fertige Abwehrstoffe gegen das RS-Virus, ohne dass das eigene Immunsystem diese erst bilden muss. Nirsevimab ist ein menschlicher monoklonaler Antikörper, der das Fusionsprotein (F-Protein) des RS-Virus in seiner Ausgangsform bindet und so das Eindringen des Virus in die Zellen verhindert. Durch eine Veränderung im Antikörper hält der Schutz mindestens 5 Monate an, sodass eine einzige Dosis für eine Saison genügt.","nebenwirkungen":{"gelegentlich":["Hautausschlag","Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerz)","Fieber"],"unbekannt":["Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nicht zutreffend – das Mittel ist für Säuglinge und Kleinkinder bestimmt.","stillzeit":"Nicht zutreffend – Stillen des behandelten Säuglings ist ohne Einschränkung möglich.","hinweise":["Eine einzelne Spritze vor oder während der RSV-Saison (Herbst/Winter); Neugeborene wenn möglich bereits kurz nach der Geburt.","Kann gleichzeitig mit den üblichen Säuglingsimpfungen gegeben werden.","Ersetzt nicht die Hygienemassnahmen; bei Atemnot oder Trinkschwäche des Säuglings trotzdem ärztlich abklären lassen."],"darreichung":["Fertigspritze (Injektionslösung, intramuskulär)"]},"nitisinon":{"wirkmechanismus":"Verhindert, dass bei der erblichen Tyrosinämie Typ 1 leber- und nierenschädigende Abbauprodukte entstehen. Nitisinon hemmt das Enzym 4-Hydroxyphenylpyruvat-Dioxygenase, das im Abbauweg der Aminosäure Tyrosin vor dem defekten Enzym (Fumarylacetoacetat-Hydrolase) liegt. Dadurch werden die giftigen Zwischenprodukte Maleyl- und Fumarylacetoacetat sowie Succinylaceton nicht mehr gebildet. Weil sich dafür Tyrosin im Blut anreichert, ist eine tyrosin- und phenylalaninarme Diät nötig.","nebenwirkungen":{"sehrHaeufig":["Erhöhter Tyrosinspiegel im Blut (Laborbefund)"],"haeufig":["Thrombozytopenie (Mangel an Blutplättchen)","Leukopenie und Granulozytopenie (Mangel an weissen Blutkörperchen)","Konjunktivitis (Bindehautentzündung)","Keratitis (Hornhautentzündung), Hornhauttrübung","Lichtscheu, Augenschmerzen"],"gelegentlich":["Leukozytose (Vermehrung weisser Blutkörperchen)","Blepharitis (Lidrandentzündung)","Juckreiz, Hautausschlag","Exfoliative Dermatitis (schuppende Hautentzündung)"]},"schwangerschaft":"Nur anwenden, wenn der Gesundheitszustand der Frau eine Behandlung erfordert; die Erfahrungen sind begrenzt.","stillzeit":"Kontraindiziert – während der Behandlung nicht stillen.","hinweise":["Die tyrosin- und phenylalaninarme Diät strikt einhalten; Tyrosinspiegel im Blut regelmässig kontrollieren lassen.","Augenrötung, Augenschmerzen oder Lichtempfindlichkeit sofort ärztlich abklären lassen.","Regelmässige Kontrollen von Blutbild, Leberwerten und Alpha-Fetoprotein (Früherkennung von Leberkrebs).","Immer gleich einnehmen: entweder stets mit oder stets ohne Mahlzeit."],"darreichung":["Hartkapseln","Suspension zum Einnehmen"]},"nitrofurantoin":{"wirkmechanismus":"Tötet Bakterien in der Blase ab, wirkt aber kaum im übrigen Körper. Nitrofurantoin wird in den Bakterien durch bakterielle Nitroreduktasen zu reaktiven Zwischenprodukten umgewandelt, die ribosomale Proteine, die Erbsubstanz (DNA) und Enzyme des Energiestoffwechsels schädigen. Weil der Wirkstoff rasch über die Niere ausgeschieden wird, entstehen wirksame Konzentrationen nur im Urin; für Nierenbeckenentzündungen oder Infektionen ausserhalb der Harnwege ist er deshalb nicht geeignet.","nebenwirkungen":{"haeufig":["Übelkeit, Appetitlosigkeit, Erbrechen","Kopfschmerzen","Schwindel und Benommenheit"],"gelegentlich":["Allergische Hautreaktionen (Ausschlag, Juckreiz, Nesselsucht)","Durchfall, Bauchschmerzen"],"selten":["Akute Lungenreaktionen (Fieber, Husten, Atemnot, Brustschmerzen)","Chronische Lungenveränderungen bis Lungenfibrose bei Langzeitanwendung","Periphere Polyneuropathie (Kribbeln, Taubheit, Schwäche in Armen und Beinen)","Cholestatische Gelbsucht und Hepatitis (Leberentzündung)","Hämolytische Anämie (Blutzerfall), besonders bei G6PD-Mangel","Blutbildveränderungen (Leukopenie, Agranulozytose, Thrombozytopenie)","Vorübergehender Haarausfall"],"sehrSelten":["Chronisch aktive Hepatitis, Leberversagen","Anaphylaxie (schwere allergische Reaktion) und Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, exfoliative Dermatitis)","Lupus-ähnliches Syndrom","Pankreatitis (Bauchspeicheldrüsenentzündung)","Gutartige Hirndrucksteigerung"],"unbekannt":["Arzneimittelfieber","Antibiotika-assoziierte Durchfälle bis pseudomembranöse Kolitis (Clostridioides difficile)","Aplastische Anämie"]},"schwangerschaft":"Nach ärztlicher Abwägung möglich; in den letzten Schwangerschaftswochen und unter der Geburt kontraindiziert, da beim Neugeborenen ein Blutzerfall (hämolytische Anämie) ausgelöst werden kann.","stillzeit":"Geht in geringen Mengen in die Muttermilch über. Nicht anwenden, wenn das gestillte Kind jünger als 1 Monat ist oder einen G6PD-Mangel hat bzw. haben könnte; sonst nach ärztlicher Abwägung.","hinweise":["Mit einer Mahlzeit oder mit Milch einnehmen – das verbessert Verträglichkeit und Aufnahme.","Der Urin kann sich dunkelgelb bis bräunlich verfärben; das ist harmlos.","Bei Husten, Atemnot, Fieber, Gelbsucht oder Kribbeln und Taubheitsgefühl in Händen oder Füssen sofort ärztlich melden.","Bei Langzeitvorbeugung Lungen-, Leber- und Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Retardkapseln"]},"nivolumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, sodass körpereigene Abwehrzellen Krebszellen wieder erkennen und angreifen. Nivolumab ist ein humaner IgG4-Antikörper gegen den Rezeptor PD-1 auf T-Lymphozyten. Er verhindert, dass die vom Tumor gebildeten Liganden PD-L1 und PD-L2 an PD-1 binden und die T-Zellen abschalten. Weil diese Immunbremse auch gesundes Gewebe schützt, können immunvermittelte Entzündungen in praktisch allen Organen auftreten.","nebenwirkungen":{"sehrHaeufig":["Müdigkeit","Hautausschlag, Juckreiz","Durchfall, Übelkeit","Muskel-, Knochen- und Gelenkschmerzen","Appetitlosigkeit","Husten, Atemnot","Erhöhte Leberwerte; Abnahme von Lymphozyten, Neutrophilen und Blutplättchen, Anämie (Laborwerte)"],"haeufig":["Hypothyreose (Schilddrüsenunterfunktion), Hyperthyreose","Pneumonitis (Lungenentzündung durch Immunreaktion)","Kolitis (Dickdarmentzündung), Stomatitis, Erbrechen, Bauchschmerzen, Verstopfung","Infusionsreaktionen, Überempfindlichkeit","Infekte der oberen Atemwege, Lungenentzündung","Kopfschmerzen, Schwindel, periphere Neuropathie","Vitiligo (Weissfleckenkrankheit), trockene Haut, Haarausfall","Fieber, Ödeme, Bluthochdruck, Hyperglykämie"],"gelegentlich":["Nebenniereninsuffizienz, Hypophysitis (Hirnanhangdrüsenentzündung), Thyreoiditis","Diabetes mellitus, diabetische Ketoazidose","Hepatitis","Nephritis (Nierenentzündung), Nierenversagen","Pankreatitis, Gastritis","Uveitis (Augenentzündung)","Herzrhythmusstörungen, Vorhofflimmern","Erythema multiforme, Psoriasis, Nesselsucht"],"selten":["Myokarditis (Herzmuskelentzündung), Perikarderkrankungen","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Guillain-Barré-Syndrom, Myasthenie-Syndrom, Enzephalitis","Myositis, Rhabdomyolyse (Muskelzerfall)","Sklerosierende Cholangitis (Gallengangsentzündung)","Sarkoidose"],"unbekannt":["Abstossung transplantierter Organe","Hämophagozytische Lymphohistiozytose (HLH, überschiessende Immunreaktion)","Vogt-Koyanagi-Harada-Syndrom (Entzündung von Augen, Haut und Hirnhäuten)"]},"schwangerschaft":"Nicht empfohlen, ausser der Nutzen überwiegt (der Antikörper gelangt zum Kind). Frauen müssen während und mindestens 5 Monate nach der letzten Dosis sicher verhüten.","stillzeit":"Unbekannt, ob Nivolumab in die Muttermilch übergeht; ein Risiko für das Kind ist nicht auszuschliessen – nach ärztlicher Abwägung entscheiden.","hinweise":["Neue oder stärkere Beschwerden – Durchfall, Bauchschmerzen, Husten, Atemnot, Hautausschlag, Gelbsucht, starke Müdigkeit, Kopfschmerzen, Sehstörungen – sofort melden, auch Wochen bis Monate nach der letzten Gabe.","Die Patientenkarte immer mitführen und bei jedem Arztbesuch zeigen.","Schilddrüsen-, Leber- und Nierenwerte sowie der Blutzucker werden regelmässig kontrolliert."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"noradrenalin":{"wirkmechanismus":"Hebt den Blutdruck, indem es die Blutgefässe stark verengt. Noradrenalin ist der natürliche Botenstoff des sympathischen Nervensystems; es stimuliert vor allem Alpha-1-Rezeptoren der Gefässmuskulatur und erhöht dadurch den Gefässwiderstand. Über Beta-1-Rezeptoren steigert es zusätzlich mässig die Kontraktionskraft des Herzens, während Beta-2-Rezeptoren kaum angesprochen werden. Durch den Blutdruckanstieg kann der Puls reflektorisch langsamer werden. Die Wirkung setzt sofort ein und klingt nach Ende der Infusion innerhalb weniger Minuten ab.","nebenwirkungen":{"unbekannt":["Angst, Unruhe, Schlaflosigkeit, Verwirrtheit, Schwäche","Kopfschmerzen, Zittern","Herzrasen (Tachykardie), reflektorische Bradykardie, Herzklopfen","Herzrhythmusstörungen bis Kammerflimmern","Myokardischämie (Sauerstoffmangel des Herzmuskels), Stress-Kardiomyopathie","Starker Blutdruckanstieg","Durchblutungsstörung von Fingern, Zehen und Organen bis zum Gewebeuntergang (Nekrose)","Atemnot","Übelkeit, Erbrechen","Harnverhalt","Gewebeschäden bis Nekrose bei Austritt aus der Vene (Paravasat)"]},"schwangerschaft":"Nur bei lebensbedrohlicher Situation nach ärztlicher Abwägung: Noradrenalin kann die Durchblutung der Plazenta vermindern und Wehen auslösen.","stillzeit":"Keine ausreichenden Daten; da Noradrenalin über den Darm kaum aufgenommen wird, ist ein Risiko für den Säugling unwahrscheinlich. Anwendung nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital als Dauerinfusion, möglichst über einen zentralen Venenkatheter, unter laufender Blutdruck- und EKG-Überwachung gegeben.","Austritt ins Gewebe kann schwere Schäden verursachen – Infusionsstelle regelmässig kontrollieren.","Volumenmangel sollte vorher oder gleichzeitig ausgeglichen werden; die Infusion wird schrittweise reduziert, nicht abrupt beendet."],"darreichung":["Infusionskonzentrat","Injektionslösung"]},"norethisteron":{"wirkmechanismus":"Wirkt wie das körpereigene Gelbkörperhormon und stabilisiert so die Gebärmutterschleimhaut. Norethisteron bindet an Progesteronrezeptoren und wandelt die durch Östrogen aufgebaute Schleimhaut in eine sekretorische Schleimhaut um; nach Absetzen kommt es zu einer geordneten Abbruchblutung. In höherer Dosis hemmt es die Ausschüttung der Hirnanhangshormone und damit den Eisprung. Es hat zusätzlich eine leichte androgene Wirkung, und ein kleiner Teil wird im Körper zu Ethinylestradiol umgewandelt.","nebenwirkungen":{"sehrHaeufig":["Brustspannen oder Brustschmerzen (bei Hormonersatz mit Estradiol)","Blutungen aus der Scheide, Schmierblutungen (bei Hormonersatz mit Estradiol)"],"haeufig":["Kopfschmerzen","Übelkeit","Gewichtszunahme, Wassereinlagerungen (Ödeme)","Depressive Verstimmung","Scheidenpilz oder Scheidenentzündung","Rückenschmerzen"],"gelegentlich":["Migräne","Libidoveränderungen, Nervosität","Bauchschmerzen, Blähungen","Akne, Haarausfall, vermehrte Behaarung, Juckreiz","Oberflächliche Venenentzündung (Thrombophlebitis)","Überempfindlichkeitsreaktionen"],"selten":["Venöse Thromboembolie (Beinvenenthrombose, Lungenembolie)"],"unbekannt":["Cholestatische Gelbsucht (Gallenstau)","Chloasma (bräunliche Pigmentflecken)","Nesselsucht, Hautausschlag","Herzinfarkt und Schlaganfall (Klassenrisiko bei Hormonersatz)"]},"schwangerschaft":"Kontraindiziert. Hohe Dosen von Nortestosteron-Gestagenen können bei weiblichen Feten zu einer Vermännlichung der äusseren Geschlechtsorgane führen; vor Behandlungsbeginn eine Schwangerschaft ausschliessen.","stillzeit":"Nicht empfohlen – Norethisteron geht in die Muttermilch über.","hinweise":["Norethisteron als Einzelpräparat ist in der eingesetzten Form kein zuverlässiges Verhütungsmittel; bei Bedarf nichthormonal verhüten.","Bei Zeichen einer Thrombose (geschwollenes, schmerzhaftes Bein, Brustschmerz, plötzliche Atemnot), erstmaliger Migräne oder Sehstörungen sofort absetzen und ärztlichen Rat einholen.","Bei Hormonersatz Nutzen und Risiken mindestens jährlich ärztlich überprüfen lassen."],"darreichung":["Tabletten","Filmtabletten (Kombination mit Estradiol)"]},"nystatin":{"wirkmechanismus":"Tötet Hefepilze ab, indem es ihre Zellhülle durchlöchert. Nystatin bindet an Ergosterol, einen Baustein der Pilzzellmembran, und bildet Poren, durch die lebenswichtige Zellbestandteile austreten; je nach Konzentration wirkt es pilzhemmend oder pilzabtötend, vor allem auf Candida-Arten. Aus dem Magen-Darm-Trakt und über die intakte Haut wird Nystatin praktisch nicht aufgenommen; es wirkt deshalb nur dort, wo es aufgetragen oder geschluckt wird, und eignet sich nicht zur Behandlung von Pilzinfektionen innerer Organe.","nebenwirkungen":{"sehrSelten":["Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Übelkeit, Erbrechen, Durchfall (v. a. bei hohen Dosen)","Reizung der Mundschleimhaut","Überempfindlichkeitsreaktionen wie Hautausschlag oder Nesselsucht","Hautreizung oder Kontaktekzem bei Anwendung auf der Haut"]},"schwangerschaft":"Wird praktisch nicht aufgenommen; die Anwendung ist nach Rücksprache mit Ärztin oder Arzt möglich.","stillzeit":"Wird praktisch nicht aufgenommen; Anwendung in der Stillzeit möglich.","hinweise":["Suspension nach den Mahlzeiten einnehmen und möglichst lange im Mund verteilen, bevor sie geschluckt wird.","Behandlung nach Abklingen der Beschwerden noch etwa 2 Tage fortsetzen, um Rückfälle zu vermeiden.","Bei Säuglingen mit Mundsoor Sauger und Nuggi regelmässig auskochen; bei stillenden Müttern auch die Brustwarzen mitbehandeln lassen."],"darreichung":["Suspension zum Einnehmen","Paste (Kombination mit Zinkoxid)"]}});
